package org.solaris.receiver;
import android.app.Activity;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.security.keystore.*;import android.util.Base64;import org.json.*;import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.util.UUID;

final class DiskBridge {
 private final Activity app;private final SharedPreferences prefs;private final File folder;
 DiskBridge(Activity a){app=a;prefs=a.getSharedPreferences("solaris-disk",Context.MODE_PRIVATE);folder=new File(a.getFilesDir(),"transfers");folder.mkdirs();}
 static String safeName(String s){s=s.replaceAll("[\\p{Cntrl}/\\\\:*?\"<>|]","_").replaceAll("^[. ]+|[. ]+$","");return s.isEmpty()?"download":s.substring(0,Math.min(160,s.length()));}
 private JSONObject entry(String id)throws Exception{UUID.fromString(id);String value=prefs.getString("file:"+id,null);if(value==null)throw new IOException("파일을 다시 선택하세요.");return new JSONObject(value);}
 private void save(String id,JSONObject e){prefs.edit().putString("file:"+id,e.toString()).commit();}
 JSONObject source(Uri uri)throws Exception{String name="file";long size=-1;try(Cursor c=app.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){name=c.getString(0);if(!c.isNull(1))size=c.getLong(1);}}if(size<0)throw new IOException("파일 크기를 확인할 수 없습니다. 기기에 저장된 파일을 선택하세요.");String id=UUID.randomUUID().toString();save(id,new JSONObject().put("source",true).put("uri",uri.toString()).put("name",name).put("size",size));return new JSONObject().put("id",id).put("name",name).put("size",size).put("modified",0);}
 JSONObject receiver(Uri destination,JSONObject a)throws Exception{String id=a.getString("id");UUID.fromString(id);long size=a.getLong("size");if(size<0||size>16L*1024*1024*1024*1024)throw new IOException("Invalid size");if(folder.getUsableSpace()<Math.min(size,64L*1024*1024))throw new IOException("저장 공간이 부족합니다.");File file=new File(folder,id+".part");try(FileOutputStream f=new FileOutputStream(file,false)){}String name=safeName(a.getString("name"));save(id,new JSONObject().put("source",false).put("uri",destination.toString()).put("name",name).put("size",size));return new JSONObject().put("id",id).put("name",name);}
 private SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(ks.containsAlias("SolarisVault"))return(SecretKey)ks.getKey("SolarisVault",null);KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("SolarisVault",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return gen.generateKey();}
 Object command(String cmd,JSONObject a)throws Exception{
  if(cmd.equals("vaultGet")||cmd.equals("vaultSet")){String k=a.getString("key");if(!k.equals("session")&&!k.equals("turn"))throw new IOException("Invalid vault key");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");if(cmd.equals("vaultGet")){String stored=prefs.getString("vault:"+k,null);if(stored==null)return null;JSONObject v=new JSONObject(stored);c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(v.getString("iv"),Base64.NO_WRAP)));return new String(c.doFinal(Base64.decode(v.getString("data"),Base64.NO_WRAP)),StandardCharsets.UTF_8);}String v=a.getString("value");if(v.length()>65536)throw new IOException("Vault value too large");c.init(Cipher.ENCRYPT_MODE,key());prefs.edit().putString("vault:"+k,new JSONObject().put("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).put("data",Base64.encodeToString(c.doFinal(v.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP)).toString()).commit();return true;}
  if(cmd.equals("diagnostics")){Runtime r=Runtime.getRuntime();return new JSONObject().put("version","0.4.0-build56").put("platform","android").put("os",Build.VERSION.RELEASE).put("memoryBytes",r.totalMemory()-r.freeMemory()).put("cpuMilliseconds",android.os.Process.getElapsedCpuTime());}
  String id=a.getString("id");JSONObject e=entry(id);boolean source=e.getBoolean("source");File partial=new File(folder,id+".part");Uri uri=Uri.parse(e.getString("uri"));long size=e.getLong("size");
  if(cmd.equals("fileInfo")){if(!source&&!e.optBoolean("complete"))return partial.exists()?new JSONObject().put("size",partial.length()):null;try(ParcelFileDescriptor fd=app.getContentResolver().openFileDescriptor(uri,"r")){return fd==null?null:new JSONObject().put("size",fd.getStatSize());}}
  if(cmd.equals("hashFile")){MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=source||e.optBoolean("complete")?app.getContentResolver().openInputStream(uri):new FileInputStream(partial)){if(in==null)throw new IOException("파일 접근 실패");byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1)hash.update(bytes,0,n);}StringBuilder hex=new StringBuilder();for(byte b:hash.digest())hex.append(String.format("%02x",b&255));return new JSONObject().put("sha256",hex.toString());}
  if(cmd.equals("readFile")){long offset=a.getLong("offset");int length=a.getInt("length");if(!source||offset<0||offset>size||length<0||length>32768)throw new IOException("Invalid read");try(ParcelFileDescriptor fd=app.getContentResolver().openFileDescriptor(uri,"r");FileInputStream f=new FileInputStream(fd.getFileDescriptor())){FileChannel channel=f.getChannel();if(channel.size()!=size)throw new IOException("원본 파일이 변경되었습니다.");channel.position(offset);ByteBuffer b=ByteBuffer.allocate((int)Math.min(length,size-offset));while(b.hasRemaining()&&channel.read(b)>0){}if(b.hasRemaining())throw new IOException("원본 파일 읽기 실패");return new JSONObject().put("data",Base64.encodeToString(b.array(),Base64.NO_WRAP));}}
  if(cmd.equals("writeFile")){byte[] bytes=Base64.decode(a.getString("data"),Base64.NO_WRAP);long offset=a.getLong("offset");if(source||offset<0||bytes.length>32768||offset+bytes.length>size)throw new IOException("Invalid write");try(RandomAccessFile f=new RandomAccessFile(partial,"rw")){if(offset>f.length())throw new IOException("Noncontiguous write");f.seek(offset);f.write(bytes);f.getFD().sync();}return true;}
  if(cmd.equals("finishFile")){if(source||a.getLong("size")!=size)throw new IOException("Incomplete file");if(e.optBoolean("complete"))return new JSONObject().put("id",id).put("name",e.getString("name"));if(partial.length()!=size)throw new IOException("Incomplete file");try(InputStream in=new FileInputStream(partial);OutputStream out=app.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("저장 위치 접근 실패");byte[] buffer=new byte[1024*1024];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);out.flush();}e.put("complete",true);save(id,e);partial.delete();return new JSONObject().put("id",id).put("name",e.getString("name"));}
  if(cmd.equals("discardFile")){if(!source)partial.delete();prefs.edit().remove("file:"+id).commit();return true;}
  throw new IOException("Unknown Solaris command");
 }
 void exportFile(String id)throws Exception{JSONObject e=entry(id);Uri uri=Uri.parse(e.getString("uri"));Intent send=new Intent(Intent.ACTION_SEND).setType("application/octet-stream").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);app.startActivity(Intent.createChooser(send,"파일 저장 / 공유"));}
}
